const groups={},tests=[];let lines=[];const test=(name,run)=>tests.push({name,run});const log=(...args)=>lines.push(args.join(' '));async function runTests(){for(const {name,run}of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};
test('frozen-text-removal',()=>{const p=document.createElement('div'),t=document.createTextNode('a');p.append(t);Object.freeze(t);log('remove',attempt(()=>p.removeChild(t)===t),p.childNodes.length,t.parentNode===null)});
test('frozen-text-split',()=>{const p=document.createElement('div'),t=document.createTextNode('abcd');p.append(t);Object.freeze(t);let c;log('split',attempt(()=>{c=t.splitText(2)}),t.data,c?.data,p.childNodes.length,c?.previousSibling===t)});
test('frozen-parent-append',()=>{const p=document.createElement('div'),t=document.createTextNode('a');Object.freeze(p);log('append',attempt(()=>p.appendChild(t)===t),p.childNodes.length,t.parentNode===p)});
test('frozen-element-removal',()=>{const p=document.createElement('div'),c=document.createElement('b');p.append(c);Object.freeze(c);log('remove',attempt(()=>p.removeChild(c)===c),p.childNodes.length,c.parentNode===null)});
test('node-symbols',()=>{const p=document.createElement('div'),t=document.createTextNode('a');p.append(t);log('symbols',Object.getOwnPropertySymbols(p).length,Object.getOwnPropertySymbols(t).length)});
test('frozen-parent-text',()=>{const p=document.createElement('div');p.append('old');Object.freeze(p);log('replace',attempt(()=>{p.textContent='new'}),p.textContent,p.childNodes.length)});
test('frozen-attribute-value',()=>{const p=document.createElement('div');p.setAttribute('x','old');const a=p.getAttributeNode('x');Object.freeze(a);Object.freeze(p);log('attr',attempt(()=>p.setAttribute('x','new')),a.value,p.getAttribute('x'),a.ownerElement===p)});
test('frozen-comment-edit',()=>{const p=document.createElement('div'),c=document.createComment('old');p.append(c);Object.freeze(c);log('comment',attempt(()=>c.appendData('!')),c.data,attempt(()=>p.removeChild(c)===c),p.childNodes.length)});
test('frozen-clone',()=>{const p=document.createElement('div');p.setAttribute('x','1');p.append('hello',document.createElement('b'));Object.freeze(p);Object.freeze(p.firstChild);let c;log('clone',attempt(()=>{c=p.cloneNode(true)}),c?.outerHTML,c?.firstChild!==p.firstChild,p.outerHTML)});
test('frozen-adoption',()=>{const a=new DOMParser().parseFromString('<!doctype html><body>','text/html'),b=new DOMParser().parseFromString('<!doctype html><body>','text/html'),p=a.createElement('p'),t=a.createTextNode('hi');p.append(t);a.body.append(p);Object.freeze(t);Object.freeze(p);log('adopt',attempt(()=>b.body.appendChild(p)===p),p.ownerDocument===b,t.ownerDocument===b,a.body.childNodes.length,p.parentNode===b.body)});
test('frozen-template',()=>{const t=document.createElement('template');Object.freeze(t);log('template',attempt(()=>t.content.append('hello')),t.content.textContent,t.innerHTML)});
test('user-symbol-slots',()=>{const e=document.createElement('b'),t=document.createTextNode('ab'),s=Symbol('next'),v=Symbol('value');let calls=0;Object.defineProperty(e,s,{get(){calls++;return 'author'}});Object.defineProperty(t,v,{get(){calls++;return 'author'}});Object.freeze(e);Object.freeze(t);log('symbols',attempt(()=>e.appendChild(t)===t),attempt(()=>t.appendData('c')),e.textContent,t.data,Object.getOwnPropertySymbols(e)[0]===s,Object.getOwnPropertySymbols(t)[0]===v,calls)});
test('frozen-style-cache',()=>{const e=document.createElement('div');Object.freeze(e);log('style',attempt(()=>e.style.setProperty('color','red')),e.style.getPropertyValue('color'),e.getAttribute('style').replace(/\s/g,'').replace(/;$/,''))});
test('node-symbols-all',()=>{const values=[document,document.createDocumentFragment(),document.createElement('b'),document.createAttribute('x'),document.createTextNode('x'),document.createComment('x'),new DOMParser().parseFromString('<!doctype html><body>','text/html').doctype];log('own symbols',values.map(v=>Object.getOwnPropertySymbols(v).length).join(','))});
test('frozen-sibling-insert',()=>{const p=document.createElement('div'),a=document.createTextNode('a'),b=document.createElement('b');p.append(a,b);Object.freeze(p);Object.freeze(a);Object.freeze(b);const c=document.createTextNode('c');log('insert',attempt(()=>p.insertBefore(c,b)===c),p.textContent,p.childNodes.length,c.previousSibling===a,c.nextSibling===b)});
